# NCCL Device API Examples
EXAMPLES = 01_allreduce_lsa 02_alltoall_gin 03_alltoall_hybrid 04_cft_barrier 05_allgather_cft_counted 06_allgather_cft_multimem_counted

# Default target
all: $(EXAMPLES)

# Build individual examples
$(EXAMPLES):
	$(MAKE) -C $@/c

# Clean all build artifacts
clean:
	for example in $(EXAMPLES); do \
		$(MAKE) -C $$example/c clean; \
	done

# Test all examples
test: all
	for example in $(EXAMPLES); do \
		echo "Testing $$example..."; \
		$(MAKE) -C $$example/c test || exit 1; \
	done

# Install all examples
install: all
	for example in $(EXAMPLES); do \
		echo "Installing $$example..."; \
		$(MAKE) -C $$example/c install || exit 1; \
	done

# Help
help:
	@echo "NCCL Device API Examples"
	@echo "========================"
	@echo ""
	@echo "Targets:"
	@echo "  all     - Build all examples"
	@echo "  clean   - Clean all build artifacts"
	@echo "  test    - Test all examples"
	@echo "  install - Install all examples"
	@echo "  help    - Show this help"
	@echo ""
	@echo "Examples:"
	@echo "  01_allreduce_lsa          - AllReduce collective operation"
	@echo "  02_alltoall_gin           - Pure GIN AlltoAll (network-only)"
	@echo "  03_alltoall_hybrid        - Hybrid GIN+LSA AlltoAll (optimized)"
	@echo "  04_cft_barrier            - CFT barrier"
	@echo "  05_allgather_cft_counted  - CFT counted AllGather"
	@echo "  06_allgather_cft_multimem_counted - CFT multimem counted AllGather"
	@echo ""
	@echo "To build/run individual examples:"
	@echo "  make -C 01_allreduce_lsa/c"
	@echo "  make -C 02_alltoall_gin/c"
	@echo "  make -C 03_alltoall_hybrid/c"
	@echo "  make -C 04_cft_barrier/c"
	@echo "  make -C 05_allgather_cft_counted/c"
	@echo "  make -C 06_allgather_cft_multimem_counted/c"

.PHONY: all clean test install help $(EXAMPLES)

[package]
name = "nccl4rust-cuda-oxide-smoke"
description = "CUDA-Oxide compile-and-link smoke kernels for nccl4rust"
version = "0.1.0"
edition = "2024"
license = "Apache-2.0"
publish = false

[workspace]
resolver = "3"

[dependencies]
cuda-device = { git = "https://github.com/NVlabs/cuda-oxide.git", rev = "c9a55dfb5e7c06f17aa8a50c1d17ae8bfa984fda" }
cuda-host = { git = "https://github.com/NVlabs/cuda-oxide.git", rev = "c9a55dfb5e7c06f17aa8a50c1d17ae8bfa984fda" }
cuda-core = { git = "https://github.com/NVlabs/cuda-oxide.git", rev = "c9a55dfb5e7c06f17aa8a50c1d17ae8bfa984fda" }
libnvvm-sys = { git = "https://github.com/NVlabs/cuda-oxide.git", rev = "c9a55dfb5e7c06f17aa8a50c1d17ae8bfa984fda" }
nvjitlink-sys = { git = "https://github.com/NVlabs/cuda-oxide.git", rev = "c9a55dfb5e7c06f17aa8a50c1d17ae8bfa984fda" }
nccl-device = { path = "../../crates/nccl-device", features = ["cuda-oxide"] }

[lints.rust]
unsafe_op_in_unsafe_fn = "warn"
